// Database row types for the People Manager (staff leave) tables and view
// (migration 421). src/types/database.ts is generated by
// `supabase gen types` and must not be edited by hand; import these shapes
// until it includes the new tables.
//
// Dates are ISO `YYYY-MM-DD` strings, timestamps ISO strings, and day
// counts numbers (numeric(4,1) in Postgres, so halves only).

export const LEAVE_REQUEST_STATUSES = [
  "pending",
  "approved",
  "declined",
  "cancelled",
] as const;
export type LeaveRequestStatus = (typeof LEAVE_REQUEST_STATUSES)[number];

/** full = the whole day; am = until lunch; pm = from the afternoon. */
export const LEAVE_DAY_PARTS = ["full", "am", "pm"] as const;
export type LeaveDayPart = (typeof LEAVE_DAY_PARTS)[number];

/** Allowed on start_part of a multi-day request. */
export const LEAVE_START_PARTS = ["full", "pm"] as const;
/** Allowed on end_part of a multi-day request. */
export const LEAVE_END_PARTS = ["full", "am"] as const;

/** Base default slugs seeded by 421 (department_id null). */
export const LEAVE_DEFAULT_TYPE_SLUGS = [
  "annual",
  "sick",
  "family",
  "study",
  "ministry_travel",
  "unpaid",
] as const;
export type LeaveDefaultTypeSlug = (typeof LEAVE_DEFAULT_TYPE_SLUGS)[number];

/** Yearly guideline days seeded for the base defaults. null = uncapped. */
export const LEAVE_DEFAULT_ALLOWANCES: Record<
  LeaveDefaultTypeSlug,
  number | null
> = {
  annual: 15,
  sick: 5,
  family: 3,
  study: 5,
  ministry_travel: null,
  unpaid: null,
};

/** Slug format enforced by the leave_types CHECK. */
export const LEAVE_TYPE_SLUG_PATTERN = /^[a-z][a-z0-9_]{1,39}$/;

/** Error codes raised by migration 421 (the RAISE message). */
export const LEAVE_ERROR_CODES = {
  leave_request_not_signed_in: "42501",
  leave_request_not_requester: "42501",
  leave_request_not_member: "42501",
  leave_request_must_start_pending: "42501",
  leave_request_immutable: "42501",
  leave_request_server_only: "42501",
  leave_request_self_decision: "42501",
  leave_request_not_approver: "42501",
  leave_request_already_decided: "42501",
  leave_request_locked: "42501",
  leave_request_cancel_not_allowed: "42501",
  leave_blockout_immutable: "42501",
  leave_request_type_not_available: "23514",
  leave_request_bad_range: "23514",
  leave_request_no_working_days: "23514",
  leave_request_decline_note_required: "23514",
  leave_days_bad_range: "22023",
} as const;
export type LeaveErrorCode = keyof typeof LEAVE_ERROR_CODES;

/**
 * leave_types. department_id null = a base default for every department;
 * a department row with the same slug overrides it for that department.
 */
export interface LeaveType {
  id: string;
  department_id: string | null;
  slug: string;
  label: string;
  sort_order: number;
  is_active: boolean;
  /** Yearly guideline days; null = uncapped. Guidance only. */
  annual_allowance_days: number | null;
  updated_by: string | null;
  created_at: string;
  updated_at: string;
}

/** leave_effective_types(department_id): what that department's form offers. */
export interface LeaveEffectiveType {
  id: string;
  department_id: string | null;
  slug: string;
  label: string;
  sort_order: number;
  is_active: boolean;
  annual_allowance_days: number | null;
  is_override: boolean;
}

/** leave_declared_holidays. One-off public holidays (admin-managed). */
export interface LeaveDeclaredHoliday {
  day: string;
  name: string;
  created_by: string | null;
  created_at: string;
}

export interface LeaveSlackNotice {
  leader_id?: string;
  channel_id?: string;
  ts?: string;
  ok?: boolean;
  error?: string;
}

/** leave_requests. */
export interface LeaveRequest {
  id: string;
  department_id: string;
  requester_id: string;
  leave_type_id: string;
  start_date: string;
  end_date: string;
  start_part: LeaveDayPart;
  end_part: LeaveDayPart;
  /** Server-computed at insert; never changes. */
  days_count: number;
  /** Server-computed split by leave year, e.g. { "2026": 3, "2027": 2.5 }. */
  days_by_year: Record<string, number>;
  notes: string | null;
  covering_user_id: string | null;
  covering_note: string | null;
  status: LeaveRequestStatus;
  decided_by: string | null;
  decided_at: string | null;
  decision_note: string | null;
  cancelled_by: string | null;
  cancelled_at: string | null;
  /** Written by the Hub server only. */
  slack_notify: LeaveSlackNotice[];
  created_at: string;
  updated_at: string;
}

/** Columns a signed-in member sends to ask for leave. */
export type LeaveRequestInsert = Pick<
  LeaveRequest,
  "department_id" | "leave_type_id" | "start_date" | "end_date"
> &
  Partial<
    Pick<
      LeaveRequest,
      "start_part" | "end_part" | "notes" | "covering_user_id" | "covering_note"
    >
  >;

/** leave_blockouts. A person's unavailable whole days; not leave. */
export interface LeaveBlockout {
  id: string;
  user_id: string;
  department_id: string | null;
  start_date: string;
  end_date: string;
  reason: string | null;
  created_at: string;
  updated_at: string;
}

/** leave_balances (security_invoker view). */
export interface LeaveBalance {
  requester_id: string;
  department_id: string;
  leave_year: number;
  type_slug: string;
  type_label: string;
  annual_allowance_days: number | null;
  used_days: number;
  pending_days: number;
  /** null when uncapped; negative when over. */
  remaining_days: number | null;
  /** null when uncapped; 0 when within the guideline. */
  over_days: number | null;
}

/** leave_department_away(department_id, from, to). Dates and status only. */
export interface LeaveAwayRow {
  user_id: string;
  source: "leave" | "blockout";
  status: Extract<LeaveRequestStatus, "pending" | "approved"> | null;
  start_date: string;
  end_date: string;
  start_part: LeaveDayPart;
  end_part: LeaveDayPart;
}

/** leave_request_approvers(request_id). Service role only. */
export interface LeaveApprover {
  user_id: string;
  via: "leader" | "admin";
}
